    ('c930964b-b6de-4f06-a421-af0c183431fc'::uuid, 'period_start', '-800', '-200', 'fields-wd5-2026-10-25p-s008:c930964b-b6de-4f06-a421-af0c183431fc:period_start', 'fields-wd5-2026-10-25p-s008 (wd5-replace): ''-800'' -> ''-200''', '[{"source": "https://www.moretonhampstead.org.uk/glimpses-of-the-past/farming/prehistoric-farming/", "url": "https://www.moretonhampstead.org.uk/glimpses-of-the-past/farming/prehistoric-farming/", "quote": "Wooston Castle has also earthwork remains of an Iron Age multivallate hillfort dated to 2nd-1st century BC by comparison with similar earthworks excavated elsewhere.", "outcome": "found"}, {"source": "http://www.dartmoorwalks.org.uk/resource/site.php?SiteID=653", "url": "http://www.dartmoorwalks.org.uk/resource/site.php?SiteID=653", "quote": "Dated to 2nd-1st century BC by comparison with similar earthworks which have been excavated.", "outcome": "found"}, {"source": "WD5 decision (counted, round 0, field_researcher:wd5-r0-b0054)", "decision": "replace", "status": "MISSING", "reasoning": "The Moretonhampstead History Society and Dartmoor Walks (from the Dartmoor HER) date Wooston Castle near Moretonhampstead, Devon, to the 2nd-1st century BC by comparison with excavated earthworks, so the start is the 2nd century BC (-200), in the 500 BC-1 AD bucket, not the stored 1500-500 BC. This is a hedged, comparison-based date: the 2018 excavation found no datable evidence to confirm the assumed Iron Age date,; the Historic England and Heritage Gateway pages could not be read by me (403), which is not a finding.", "value_page": null, "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)", "adversarial": {"answered_by": "adversarial:adv-r1-b0004", "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)", "reason": "Both pages give 2nd-1st century BC only ''by comparison with similar earthworks'', and the Dartmoor Walks page quotes the HER that the 2018 excavation ''found no dateable evidence to confirm the assumed Iron Age date''; no excavation, radiocarbon or register source dates this fort''s start, and Historic England/Heritage Gateway were not readable (403, not a finding), so -200 is an analogy-based assumption that the sources I reached do not settle.", "round": 1, "verdict": "unclear"}, "owner": {"at": "2026-10-25T07:49:50+00:00", "decision": "D69", "reason": "owner 2026-10-25 (D69): write the researcher''s value with its found quote for a cell the re-check held as unclear"}}]'::jsonb),
    ('cbc93ea2-6ae5-4be6-a320-254960a60ab7'::uuid, 'period_name', '1500 - 500 BC', '500 BC - 1 AD', 'fields-wd5-2026-10-25p-s008:cbc93ea2-6ae5-4be6-a320-254960a60ab7:period_name', 'fields-wd5-2026-10-25p-s008 (wd5-derive-period-name): period_start -500 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-500) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}, {"source": "WD5 decision (counted, round 0, field_researcher:wd5-r0-b0125)", "decision": "replace", "status": "MISSING", "reasoning": "The site is the Jordbro grave field (RAA Osterhaninge 182:1, Haninge). English Wikipedia and GuidebookSweden date the graves from 500 BC to 500 AD, so the start is -500 (band 500 BC - 1 AD); Haninge municipality''s own brochure likewise puts the oldest graves at about 500 BC, the turn from Bronze to Iron Age, and German Wikipedia says most objects are 500 BC - 500 AD. The Stockholm University excavation (Fahlander and Vinberg 2023, cited by Swedish Wikipedia) found three small Younger Bronze Age graves and Stone Age settlement traces on the field, but gives no year quotable from a readable page and the Younger Bronze Age ends at 500 BC, so this does not contradict a start about 500 BC; the stored -800 is a rule value.", "value_page": null, "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)", "adversarial": {"answered_by": "adversarial:adv-r1-b0008", "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)", "reason": "English Wikipedia and GuidebookSweden date the visible monuments to 500 BC - 500 AD, but Swedish Wikipedia, citing the Stockholm University excavation reports (Fahlander and Vinberg 2023, Fahlander 2024), reports three smaller Younger Bronze Age graves and Stone Age settlement traces under the later graves, so the field''s first burials may predate 500 BC and the sources I could open give no year for them.", "round": 1, "verdict": "unclear"}, "owner": {"at": "2026-10-25T07:49:50+00:00", "decision": "D69", "reason": "owner 2026-10-25 (D69): write the researcher''s value with its found quote for a cell the re-check held as unclear"}}]'::jsonb),
    ('cbc93ea2-6ae5-4be6-a320-254960a60ab7'::uuid, 'period_start', '-800', '-500', 'fields-wd5-2026-10-25p-s008:cbc93ea2-6ae5-4be6-a320-254960a60ab7:period_start', 'fields-wd5-2026-10-25p-s008 (wd5-replace): ''-800'' -> ''-500''', '[{"source": "https://en.wikipedia.org/wiki/Jordbro_Grave_Field", "url": "https://en.wikipedia.org/wiki/Jordbro_Grave_Field", "quote": "The grave field consists of 660 graves which are historical monuments dating from 500 BC to 500 AD.", "outcome": "found"}, {"source": "https://www.guidebook-sweden.com/en/guidebook/destination/jordbro-gravfaelt-grave-field-jordbro", "url": "https://www.guidebook-sweden.com/en/guidebook/destination/jordbro-gravfaelt-grave-field-jordbro", "quote": "Most of the graves in the Jordbro grave field date from 500 BC to 500 AD", "outcome": "found"}, {"source": "WD5 decision (counted, round 0, field_researcher:wd5-r0-b0125)", "decision": "replace", "status": "MISSING", "reasoning": "The site is the Jordbro grave field (RAA Osterhaninge 182:1, Haninge). English Wikipedia and GuidebookSweden date the graves from 500 BC to 500 AD, so the start is -500 (band 500 BC - 1 AD); Haninge municipality''s own brochure likewise puts the oldest graves at about 500 BC, the turn from Bronze to Iron Age, and German Wikipedia says most objects are 500 BC - 500 AD. The Stockholm University excavation (Fahlander and Vinberg 2023, cited by Swedish Wikipedia) found three small Younger Bronze Age graves and Stone Age settlement traces on the field, but gives no year quotable from a readable page and the Younger Bronze Age ends at 500 BC, so this does not contradict a start about 500 BC; the stored -800 is a rule value.", "value_page": null, "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)", "adversarial": {"answered_by": "adversarial:adv-r1-b0008", "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)", "reason": "English Wikipedia and GuidebookSweden date the visible monuments to 500 BC - 500 AD, but Swedish Wikipedia, citing the Stockholm University excavation reports (Fahlander and Vinberg 2023, Fahlander 2024), reports three smaller Younger Bronze Age graves and Stone Age settlement traces under the later graves, so the field''s first burials may predate 500 BC and the sources I could open give no year for them.", "round": 1, "verdict": "unclear"}, "owner": {"at": "2026-10-25T07:49:50+00:00", "decision": "D69", "reason": "owner 2026-10-25 (D69): write the researcher''s value with its found quote for a cell the re-check held as unclear"}}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 10;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a curated site that still exists
    SELECT count(*) INTO bad
      FROM _fields_wd5_plan p LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'WD5 field correction: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _fields_wd5_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'lat' THEN p.new_value::double precision IS NOT DISTINCT FROM p.old_value::double precision OR p.new_value IS NULL OR p.old_value IS NULL
                WHEN 'lon' THEN p.new_value::double precision IS NOT DISTINCT FROM p.old_value::double precision OR p.new_value IS NULL OR p.old_value IS NULL
                WHEN 'geom' THEN p.new_value::geometry IS NOT DISTINCT FROM p.old_value::geometry OR p.new_value IS NULL
                WHEN 'period_start' THEN p.new_value::integer IS NOT DISTINCT FROM p.old_value::integer
                WHEN 'period_name' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 100
                WHEN 'site_type' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 100
                WHEN 'source_url' THEN p.new_value::text IS NOT DISTINCT FROM p.old_value::text
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD5 field correction: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _fields_wd5_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'lat' THEN u.lat IS DISTINCT FROM p.old_value::double precision
                WHEN 'lon' THEN u.lon IS DISTINCT FROM p.old_value::double precision
                WHEN 'geom' THEN u.geom IS DISTINCT FROM p.old_value::geometry
                WHEN 'period_start' THEN u.period_start IS DISTINCT FROM p.old_value::integer
                WHEN 'period_name' THEN u.period_name IS DISTINCT FROM p.old_value::character varying
                WHEN 'site_type' THEN u.site_type IS DISTINCT FROM p.old_value::character varying
                WHEN 'source_url' THEN u.source_url IS DISTINCT FROM p.old_value::text
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD5 field correction: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 4: every planned row writes a value this lane owns (new value)
    SELECT count(*) INTO bad FROM _fields_wd5_plan p
     WHERE CASE p.column_name
                WHEN 'period_name' THEN p.new_value NOT IN ('< 4500 BC', '4500 - 3000 BC', '3000 - 1500 BC', '1500 - 500 BC', '500 BC - 1 AD', '1 - 500 AD', '500 - 1000 AD', '1000 - 1500 AD', '1500+ AD', 'Undated')
                WHEN 'site_type' THEN p.new_value NOT IN ('City', 'Town', 'Village', 'Settlement', 'Urban', 'Villa', 'City/town/settlement', 'Residence/villa/farmhouse', 'City/town/settlement, Pyramid complex', 'Castle', 'Citadel', 'Fort', 'Fortress', 'Military', 'Wall', 'Gate', 'Fortress/citadel', 'Castle/palace', 'Gate/archway/bridge', 'Fortification', 'Church', 'Mosque', 'Temple', 'Monastery', 'Sacred site', 'Sanctuary', 'Religious', 'Temple complex', 'Church/cathedral', 'Minaret/tower', 'Stone cross', 'Cemetery', 'Necropolis', 'Tomb', 'Burial', 'Funerary', 'Necropolis/tombs complex', 'Barrow', 'Mound/tumulus', 'Cairn', 'Elongated skulls', 'Megalithic', 'Megalithic stones', 'Megalithic structures', 'Megalithic statues', 'Megalithic walls', 'Stone circle', 'Dolmen', 'Standing stone', 'Henge', 'Timber circle', 'Polygonal masonry', 'Cave', 'Cave Structures', 'Rock relief/carving', 'Rock art', 'Petroglyphs', 'Sculptured stone', 'Cave Structures, Rock art', 'Geoglyphs', 'Road', 'Bridge', 'Mine', 'Quarry', 'Infrastructure', 'Road/avenue/trackway', 'Reservoir/aqueduct/canal', 'Mine/quarry', 'Earthwork', 'Well', 'Aqueduct', 'Bath', 'Harbor', 'Port', 'Underwater structures', 'Shipwreck', 'Monument', 'Memorial', 'Stadium', 'Theater', 'Theatre', 'Forum', 'Palace', 'Pyramid complex', 'Museum', 'Amphitheatre', 'Scheduled monument', 'Heritage site', 'Archaeological site', 'Site', 'Ruin', 'Inscription', 'Natural feature', 'Impact crater', 'Geological interest', 'Magnetic anomaly', 'Unknown')
                ELSE false END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD5 field correction: % planned row(s) write a value this lane does not own', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _fields_wd5_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'unified_sites', r.column_name, 'id', r.site_id::text,
            r.old_value, r.new_value,
            'WD5/structured-fields', '2026-10-25p_fields-wd5-s008', r.change_key, 'one_source', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'WD5 field correction: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _fields_wd5_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'lat' THEN u.lat IS DISTINCT FROM p.new_value::double precision
                WHEN 'lon' THEN u.lon IS DISTINCT FROM p.new_value::double precision
                WHEN 'geom' THEN u.geom IS DISTINCT FROM p.new_value::geometry
                WHEN 'period_start' THEN u.period_start IS DISTINCT FROM p.new_value::integer
                WHEN 'period_name' THEN u.period_name IS DISTINCT FROM p.new_value::character varying
                WHEN 'site_type' THEN u.site_type IS DISTINCT FROM p.new_value::character varying
                WHEN 'source_url' THEN u.source_url IS DISTINCT FROM p.new_value::text
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD5 field correction: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _fields_wd5_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'unified_sites'
       AND l.column_name = p.column_name
       AND l.run_stamp = '2026-10-25p_fields-wd5-s008'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD5 field correction: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = '2026-10-25p_fields-wd5-s008'
       AND (l.table_name <> 'unified_sites' OR l.column_name NOT IN ('lat', 'lon', 'geom', 'period_start', 'period_name', 'site_type', 'source_url'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD5 field correction: this run stamp journalled % row(s) outside unified_sites.(lat, lon, geom, period_start, period_name, site_type, source_url)', bad;
    END IF;

    -- site invariant: no planned site may be left with this - planned site(s) hold a geom that is not their point
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id FROM _fields_wd5_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE EXISTS (SELECT 1 FROM _fields_wd5_plan q WHERE q.site_id = p.site_id AND q.column_name IN ('lat', 'lon', 'geom')) AND u.geom IS DISTINCT FROM ST_SetSRID(ST_MakePoint(u.lon, u.lat), 4326);
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD5 field correction: % planned site(s) hold a geom that is not their point', bad;
    END IF;

    -- site invariant: no planned site may be left with this - planned site(s) hold a period_name that is not the bucket of their period_start
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id FROM _fields_wd5_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE EXISTS (SELECT 1 FROM _fields_wd5_plan q WHERE q.site_id = p.site_id AND q.column_name IN ('period_start', 'period_name')) AND u.period_name IS DISTINCT FROM (CASE WHEN u.period_start IS NULL THEN 'Undated' WHEN u.period_start < -4500 THEN '< 4500 BC' WHEN u.period_start < -3000 THEN '4500 - 3000 BC' WHEN u.period_start < -1500 THEN '3000 - 1500 BC' WHEN u.period_start < -500 THEN '1500 - 500 BC' WHEN u.period_start < 1 THEN '500 BC - 1 AD' WHEN u.period_start < 500 THEN '1 - 500 AD' WHEN u.period_start < 1000 THEN '500 - 1000 AD' WHEN u.period_start < 1500 THEN '1000 - 1500 AD' ELSE '1500+ AD' END);
    IF bad > 0 THEN
        RAISE EXCEPTION 'WD5 field correction: % planned site(s) hold a period_name that is not the bucket of their period_start', bad;
    END IF;

    RAISE NOTICE 'WD5 field correction: % of % planned cell(s) changed and journalled over 5 curated site(s)',
        moved, expected;
END $$;

COMMIT;

-- Post-commit read: the numbers the report quotes, from the database, not from the plan.
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = '2026-10-25p_fields-wd5-s008'
UNION ALL
SELECT 'journal rows for this test id', count(*)::text
  FROM remediation_change_log WHERE test_id = 'WD5/structured-fields'
UNION ALL
SELECT 'planned rows now holding the new value', count(*)::text
  FROM remediation_change_log l
 WHERE l.run_stamp = '2026-10-25p_fields-wd5-s008' AND l.table_name = 'unified_sites'
   AND l.column_name IN ('lat', 'lon', 'geom', 'period_start', 'period_name', 'site_type', 'source_url')
   AND EXISTS (SELECT 1 FROM unified_sites u
                WHERE u.id::text = l.row_pk AND CASE l.column_name
                WHEN 'lat' THEN u.lat IS NOT DISTINCT FROM l.new_value::double precision
                WHEN 'lon' THEN u.lon IS NOT DISTINCT FROM l.new_value::double precision
                WHEN 'geom' THEN u.geom IS NOT DISTINCT FROM l.new_value::geometry
                WHEN 'period_start' THEN u.period_start IS NOT DISTINCT FROM l.new_value::integer
                WHEN 'period_name' THEN u.period_name IS NOT DISTINCT FROM l.new_value::character varying
                WHEN 'site_type' THEN u.site_type IS NOT DISTINCT FROM l.new_value::character varying
                WHEN 'source_url' THEN u.source_url IS NOT DISTINCT FROM l.new_value::text
                ELSE false END)
UNION ALL
SELECT 'curated rows whose period_name is not the bucket of period_start, or not Undated where there is none', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND period_name IS DISTINCT FROM (CASE WHEN period_start IS NULL THEN 'Undated' WHEN period_start < -4500 THEN '< 4500 BC' WHEN period_start < -3000 THEN '4500 - 3000 BC' WHEN period_start < -1500 THEN '3000 - 1500 BC' WHEN period_start < -500 THEN '1500 - 500 BC' WHEN period_start < 1 THEN '500 BC - 1 AD' WHEN period_start < 500 THEN '1 - 500 AD' WHEN period_start < 1000 THEN '500 - 1000 AD' WHEN period_start < 1500 THEN '1000 - 1500 AD' ELSE '1500+ AD' END)
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds';
